import * as secp256k1 from '@noble/secp256k1';

/**
 * Key pair for ECDH key exchange
 */
interface KeyPair {
    privateKey: Uint8Array;
    publicKey: Uint8Array;
}
declare function generateECDHKeyPair(): Promise<{
    privateKey: secp256k1.Bytes;
    publicKey: secp256k1.Bytes;
}>;
declare function getSharedSecret(privateKey: Uint8Array, publicKey: Uint8Array): Promise<Uint8Array<ArrayBuffer>>;
declare function encrypt(message: string, sharedSecret: Uint8Array, nonce: string): Promise<Uint8Array<ArrayBufferLike>>;
declare function decrypt(ciphertext: Uint8Array, sharedSecret: Uint8Array, nonce: string): Promise<string>;

export { type KeyPair, decrypt, encrypt, generateECDHKeyPair, getSharedSecret };
